<script>
    const sections = document.querySelectorAll('main section');
    sections.forEach((section) => section.classList.add('opacity-0', 'transition', 'duration-1000'));
    const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
        if (entry.isIntersecting) { entry.target.classList.remove('opacity-0'); observer.unobserve(entry.target); }
    }), { threshold: 0.12 });
    sections.forEach((section) => observer.observe(section));
</script>
